INSERT OR IGNORE INTO pm_projects (id, workspace_id, title, description, status, created_at, updated_at) VALUES ('proj-learning-engine-001', 'jmbish04/core-github-api', 'AI Learning & Pattern Recognition Engine', 'A continuous improvement service that extracts all AI coding conversations (Jules, Gemini, Stitch), enriches them with Cloudflare Docs context, identifies recurring failure patterns, and automatically submits PRs to core-github-standardization to immunize future agents against known mistakes.', 'in_progress', 1774835623, 1774835623);

