INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-001-schema', 'proj-learning-engine-001', 'Database Schema — Learning Micro-Domain', 'Create all 10 Drizzle ORM schema files for the learning domain under backend/src/db/schemas/github/learning/. Reuse existing app/tags.ts — no duplicate tags table.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-002-ingestion', 'proj-learning-engine-001', 'Learning Ingestion Service', 'Port log_conversations.py logic into a TypeScript LearningIngestionService. Sources: Jules SDK (JulesService), GitHub Octokit (getOctokit), Stitch MCP. Deduplication via sourceIdentifier unique index.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-003-agent', 'proj-learning-engine-001', 'LearningAgent Durable Object', 'Stateful Durable Object agent with Contemplation Gate (anti-light-switch). Tools: enrichMessage (CF Docs), tagMessage, analyzeMessage (Workers AI), createInsight, contemplateFix (Vectorize + D1 reflection), submitImprovementPr, issueRemediationComment.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-004-workflow', 'proj-learning-engine-001', 'Cloudflare Workflow + Daily Cron', 'LearningWorkflow using Cloudflare Workflows product for durable step execution. Daily cron at 0 6 * * * UTC. Manual trigger via POST /api/learning/sync.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-005-api', 'proj-learning-engine-001', 'API Routes', 'Hono OpenAPI routes at /api/learning/ for sync trigger, session listing, insight search/filter, global standardization score, and upscale endpoint for Jules orchestration.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-006-interceptor', 'proj-learning-engine-001', 'Active PR Interceptor (Real-time Remediation)', 'Webhook-driven interceptor that fires on PR opened/synchronize events. Scans PR diff against known ai_insights patterns and posts remediation comments via user-persona token. Includes D1-backed merge queue for post-merge template hardening.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-007-frontend', 'proj-learning-engine-001', 'Frontend Control Plane (Astro + Dark Shadcn)', '4 Astro pages under frontend/src/pages/learning/: dashboard (Recharts trendlines), sessions (Shadcn Table audit log), board (kibo-ui Kanban: DETECTED→IN_VERIFICATION→IMMUNIZED), showcase (Standardization library + Upscale button).', 'todo', 'low', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_epics (id, project_id, title, description, status, priority, created_at, updated_at) VALUES ('epic-008-health', 'proj-learning-engine-001', 'Health Monitoring', 'Add /health/learning endpoint to existing health suite. Monitor AI Gateway latency, Sandbox SDK container availability, last successful learning run timestamp, open insight PR count.', 'todo', 'low', 1774835623, 1774835623);

