INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-001-01', 'epic-001-schema', 'Create 10 Drizzle schema files', 'One file per table: sessions.ts, threads.ts, messages.ts, enrichment.ts, tagMapping.ts, aiInsights.ts, aiInsightMessages.ts, aiInsightPrs.ts, aiInsightPrMapping.ts, aiPrReflections.ts. Each exported with Zod OpenAPI schemas.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-001-02', 'epic-001-schema', 'Wire schema barrel and run migration', 'Create learning/index.ts barrel. Add ''export * from ./learning'' to backend/src/db/schemas/github/index.ts. Run npm run migrate:db and verify 10 new learning_* tables in D1.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-002-01', 'epic-002-ingestion', 'Jules ingestion', 'Use existing JulesService from backend/src/services/julius/jules.ts. List all sessions + activities. Map session → learning_threads (source: jules), activities → learning_messages. Dedup by sourceIdentifier unique index.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-002-02', 'epic-002-ingestion', 'GitHub PR ingestion', 'Use getOctokit() from backend/src/services/octokit/core.ts. Search merged PRs by jmbish04. Fetch PR body + issue comments + review comments. Map PR → thread, comments → messages. Dedup by PR URL.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-002-03', 'epic-002-ingestion', 'Stitch ingestion', 'Call Stitch MCP paginated API (mirrors _sync_stitch from log_conversations.py). Map project/screen → thread, prompts → messages. Dedup by stitch/{projectId}/{screenName}.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-003-01', 'epic-003-agent', 'Core agent tools: enrich, tag, analyze', 'Implement enrichMessage (CF Docs MCP → learning_enrichment), tagMessage (query app.tags → learning_tag_mapping, createTag if new), analyzeMessage (Workers AI → messages.aiAnalysis). All inference via AI Gateway.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-003-02', 'epic-003-agent', 'Pattern detection and insight creation', 'Group threads by category. If 3+ threads share the same correction pattern → createInsight (learning_ai_insights, status: PENDING). Link messages via learning_ai_insight_messages for audit traceability.', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-003-03', 'epic-003-agent', 'Contemplation Gate (anti-light-switch)', 'Before submitting any PR: query VECTORIZE_INDEX for semantic similarity to prior patterns. Query ai_pr_reflections for prior outcomes. If category was already addressed and deemed successful → skip. If FAILED → escalate to UPGRADE_TEMPLATE target (core-github-standardization).', 'todo', 'high', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-003-04', 'epic-003-agent', 'Signal-driven vectorization', 'Only vectorize messages with ai_analysis populated OR linked to an ai_insight. Vectorize into VECTORIZE_INDEX binding. Do NOT vectorize every raw prompt — prevents noise in semantic search.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-004-01', 'epic-004-workflow', 'LearningWorkflow class', 'Create backend/src/workflows/learning.ts following pattern from backend/src/workflows/health.ts. Steps: createSession, ingestConversations, runAnalysis, finalizeSession. Each step has timeout + retry.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-004-02', 'epic-004-workflow', 'Register workflow and cron in wrangler.jsonc', 'Add to workflows array: { name: learning-workflow, class_name: LearningWorkflow, binding: LEARNING_WORKFLOW }. Add to triggers.crons: ''0 6 * * *''.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-005-01', 'epic-005-api', 'Core learning routes', 'POST /api/learning/sync (manual trigger → dispatch LearningWorkflow), GET /api/learning/sessions, GET /api/learning/insights (filter by category/status/q), GET /api/learning/insights/:id.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-005-02', 'epic-005-api', 'Upscale and global insights routes', 'GET /api/learning/insights/global (aggregated Standardization Score per category). POST /api/learning/upscale (fetch standardization files + start Jules session for active repo audit).', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-006-01', 'epic-006-interceptor', 'PR webhook interceptor', 'Wire learning-interceptor.ts into existing PR webhook handlers (backend/src/automations/pr/). On PR opened/synchronize: scan diff vs known ai_insights patterns. If match → post comment via user-persona GH token targeting assigned agent.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-006-02', 'epic-006-interceptor', 'Post-merge template hardening queue', 'After PR merge webhook: check if merged PR was flagged in learning_ai_insight_prs. If yes → trigger Jules session to apply fix to core-github-standardization. Use D1 mergeQueueStatus field to prevent duplicate triggers.', 'todo', 'medium', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-007-01', 'epic-007-frontend', '/learning/dashboard — Trendlines', 'Recharts line chart: ''Manual Corrections per PR'' vs ''Immunized Rules'' over time. Queries learning_sessions aggregated data. Dark Shadcn theme.', 'todo', 'low', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-007-02', 'epic-007-frontend', '/learning/sessions — Audit Log', 'Shadcn Table of analysis runs. Expandable Collapsible rows → threads → enrichment → CF Docs grounding responses → ai_analysis per message.', 'todo', 'low', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-007-03', 'epic-007-frontend', '/learning/board — Insight Kanban', 'kibo-ui Kanban board mapping learning_ai_insights.status: DETECTED (PENDING) → IN_VERIFICATION → IMMUNIZED. Drag-and-drop updates status via PATCH /api/learning/insights/:id.', 'todo', 'low', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-007-04', 'epic-007-frontend', '/learning/showcase — Standards Library + Upscale', 'Grid of Shadcn Cards for every standard in core-github-standardization (tsconfig.json, AGENTS.md, /health/index.ts, etc). Each card: ''View Content'' dialog (fetches raw file from GitHub) + ''Upscale Current Repo'' primary button → POST /api/learning/upscale.', 'todo', 'low', 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_stories (id, epic_id, title, description, status, priority, created_at, updated_at) VALUES ('story-008-01', 'epic-008-health', '/health/learning endpoint', 'Create backend/src/health/learning.ts. Checks: AI Gateway latency for CF Docs enrichment, Sandbox SDK container availability, last successful learning_sessions run timestamp, count of open learning_ai_insight_prs. Register in existing health suite.', 'todo', 'low', 1774835623, 1774835623);

