INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-01', 'story-001-01', 'Create sessions.ts — learning_sessions table', 'Fields: id (int PK autoincrement), timestamp (text ISO default), actionTaken (boolean default false), actionRationale (text nullable). Include createSelectSchema + createInsertSchema with .openapi().', 'todo', 'high', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-02', 'story-001-01', 'Create threads.ts — learning_threads table', 'Fields: id, sessionId FK, timestamp, source enum(jules/stitch/github_pr/github_comment/other), sourceIdentifier (unique), githubRepo. Add unique index on sourceIdentifier for deduplication.', 'todo', 'high', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-03', 'story-001-01', 'Create messages.ts — learning_messages table', 'Fields: id, sessionId FK, threadId FK, timestamp, author, message, aiAnalysis (nullable, updated post-processing). Add indexes on threadId and sessionId.', 'todo', 'high', 3, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-04', 'story-001-01', 'Create enrichment.ts — learning_enrichment table', 'Fields: id, messageId FK, timestamp (default now), queryForMcp, mcpResponse (nullable), aiAnalysis (nullable). 1:many per message for multiple CF Docs queries.', 'todo', 'high', 4, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-05', 'story-001-01', 'Create tagMapping.ts — learning_tag_mapping table', 'IMPORTANT: references existing app/tags.ts (tags.id as text FK). Fields: id, tagId (→ tags.id), messageId FK, rationale. Do NOT create a new learning_tags table.', 'todo', 'high', 5, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-06', 'story-001-01', 'Create aiInsights.ts — learning_ai_insights table', 'Fields: id, sessionId FK, threadId FK, timestamp, category, insightAnalysis, suggestedImprovement, observedAttemptsReview, status enum(PENDING/IN_VERIFICATION/IMMUNIZED/REVERTED/OBSERVED). Index on category.', 'todo', 'high', 6, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-07', 'story-001-01', 'Create aiInsightMessages.ts — learning_ai_insight_messages table', 'Links messages to insights for audit traceability. Fields: id, aiInsightId FK, messageId FK, sessionId FK.', 'todo', 'high', 7, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-08', 'story-001-01', 'Create aiInsightPrs.ts — learning_ai_insight_prs table', 'Tracks PRs submitted to fix flagged issues. Fields: id, sessionId FK, timestamp, repoOwner, repoName, prNumber, prUrl, prDescription, outcome enum(OPEN/MERGED/CLOSED/REVERTED).', 'todo', 'high', 8, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-09', 'story-001-01', 'Create aiInsightPrMapping.ts — learning_ai_insight_pr_mapping table', 'Links insights to their fix PRs. Fields: id, insightId FK, insightPrId FK, aiRationale, aiSuccessCriteria.', 'todo', 'high', 9, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-01-10', 'story-001-01', 'Create aiPrReflections.ts — learning_ai_pr_reflections table', 'Anti-light-switch guard. Fields: id, sessionId FK, newInsightId FK, priorInsightId FK (nullable), insightPrId FK (nullable), agentAnalysis, prSuccessDetermination.', 'todo', 'high', 10, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-02-01', 'story-001-02', 'Create learning/index.ts barrel', 'Export all 10 schema files from backend/src/db/schemas/github/learning/index.ts', 'todo', 'high', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-02-02', 'story-001-02', 'Update backend/src/db/schemas/github/index.ts', 'Add: export * from ''./learning''', 'todo', 'high', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-001-02-03', 'story-001-02', 'Run D1 migration', 'npm run migrate:db — verify 10 new learning_* tables created in D1 console', 'todo', 'high', 3, 1774835623, 1774835623);
