INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-002-01-02', 'story-002-01', 'Implement Jules ingestion in ingestion.ts', 'Use JulesService.listSessions() from backend/src/services/julius/jules.ts. Map session.name → sourceIdentifier, activities → messages. Skip if sourceIdentifier exists (unique constraint).', 'todo', 'high', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-002-02-01', 'story-002-02', 'Implement GitHub PR ingestion', 'Use getOctokit(env) from backend/src/services/octokit/core.ts. Query: is:pr is:merged author:jmbish04. Fetch PR body + /issues/{n}/comments + /pulls/{n}/comments (review comments). Map to threads + messages.', 'todo', 'high', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-002-03-01', 'story-002-03', 'Implement Stitch ingestion', 'Call Stitch MCP paginated API following pattern from log_conversations.py _sync_stitch method. POST /tools/stitch/scan_conversations_paginated. Map project/screen → thread, prompts → messages.', 'todo', 'medium', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-01-01', 'story-003-01', 'Implement enrichMessage tool', 'Generate CF Docs query from message content. Call cloudflare-docs MCP search tool. Insert row into learning_enrichment. Routing through AI Gateway.', 'todo', 'high', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-01-02', 'story-003-01', 'Implement tagMessage tool', 'Query existing app.tags table. Select matching tags based on message content. Insert into learning_tag_mapping. If genuinely new category (confirmed by Workers AI) → insert new row into app.tags first.', 'todo', 'high', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-01-03', 'story-003-01', 'Implement analyzeMessage tool', 'Workers AI (via AI Gateway): synthesize message + enrichment results + applied tags → update learning_messages.aiAnalysis. Model: @cf/meta/llama-3.1-8b-instruct or claude via AI Gateway.', 'todo', 'high', 3, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-02-01', 'story-003-02', 'Implement pattern detection (3-thread threshold)', 'After processing all messages: group by correction category. If same category appears in 3+ distinct threads → call createInsight. Insert learning_ai_insights row (status: PENDING).', 'todo', 'high', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-02-02', 'story-003-02', 'Link messages to insights via aiInsightMessages', 'For each new ai_insight: insert rows into learning_ai_insight_messages linking the contributing messages. Required for audit traceability.', 'todo', 'high', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-03-01', 'story-003-03', 'Implement contemplateFix tool — Vectorize semantic search', 'Generate embedding for current pattern using @cf/baai/bge-small-en-v1.5. Query VECTORIZE_INDEX (topK: 3). If matches found → mark as repeatOffender.', 'todo', 'high', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-03-02', 'story-003-03', 'Implement contemplateFix — D1 prior outcomes check', 'Query learning_ai_pr_reflections for prior entries in same category within last 90 days. If prSuccessDetermination = FAILED → action: UPGRADE_TEMPLATE (target core-github-standardization). Otherwise: SUGGEST_PATCH.', 'todo', 'high', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-003-04-01', 'story-003-04', 'Vectorize filtered messages', 'After analyzeMessage: if message has ai_analysis OR is linked to an ai_insight → generate embedding + insert into VECTORIZE_INDEX. Do not vectorize messages with no analysis.', 'todo', 'medium', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-004-01-01', 'story-004-01', 'Create LearningWorkflow class', 'backend/src/workflows/learning.ts. 4 steps: createSession (insert learning_sessions), ingestConversations (LearningIngestionService), runAnalysis (dispatch LearningAgent DO), finalizeSession (update session actionTaken). Follow health.ts pattern.', 'todo', 'medium', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-004-02-01', 'story-004-02', 'Register LearningWorkflow in wrangler.jsonc', 'Add: { name: ''learning-workflow'', class_name: ''LearningWorkflow'', binding: ''LEARNING_WORKFLOW'' } to workflows array.', 'todo', 'medium', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-004-02-02', 'story-004-02', 'Add daily cron trigger', 'Add ''0 6 * * *'' to triggers.crons in wrangler.jsonc. Wire cron handler to dispatch LearningWorkflow.', 'todo', 'medium', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-005-01-01', 'story-005-01', 'Implement POST /api/learning/sync', 'Dispatch LEARNING_WORKFLOW. Return { workflowRunId, status: ''triggered'' }.', 'todo', 'medium', 1, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-005-01-02', 'story-005-01', 'Implement GET /api/learning/sessions', 'List learning_sessions ordered by timestamp desc, limit 50. Use Zod OpenAPI schema.', 'todo', 'medium', 2, 1774835623, 1774835623);
INSERT OR IGNORE INTO pm_tasks (id, story_id, title, description, status, priority, "order", created_at, updated_at) VALUES ('task-005-01-03', 'story-005-01', 'Implement GET /api/learning/insights', 'Filter by category, status, q (like search on insightAnalysis). Ordered by timestamp desc. Use Zod OpenAPI schema.', 'todo', 'medium', 3, 1774835623, 1774835623);
